SELECT ct.id AS id, ct.tenant_id AS tenantId, st.tenant_name AS tenantName, ct.task_no AS taskNo, ct.service_id AS serviceId, ct.service_name AS serviceName, ct.source_number AS sourceNumber, ct.source_id AS sourceId, ct.customer_id AS customerId, ci.customer_name AS customerName, ct.company_id AS companyId, cc.company_name AS companyName, cc.tax_number AS taxNumber, cc.company_type AS companyType, ct.current_owner_user AS currentOwnerUser, ct.current_owner_user_name AS currentOwnerUserName, ct.owner_user AS ownerUser, ct.owner_user_name AS ownerUserName, ct.create_by AS createBy, ct.create_by_name AS createByName, ct.wish_finish_time AS wishFinishTime, ct.real_finish_time AS realFinishTime, ct.create_time AS createTime, ct.status AS status FROM common_task ct LEFT JOIN customer_company cc ON ct.company_id = cc.id LEFT JOIN customer_info ci ON ct.customer_id = ci.id LEFT JOIN sys_tenant st ON ct.tenant_id = st.id and st.deleted = 0 WHERE ct.deleted = 0
AND ct.task_no like concat('%', #{params.taskNo}, '%')
and ci.customer_name like concat('%', #{params.customerName}, '%')
AND cc.company_name like concat('%', #{params.companyName}, '%')
AND ct.source_number like concat('%', #{params.sourceNumber}, '%')
AND ct.current_owner_user_name like concat('%', #{params.currentOwnerUserName}, '%')
AND ct.status in
#{item}
and ( ct.create_by in
#{item}
or ct.owner_user in
#{item}
or ct.current_owner_user in
#{item}
or exists( SELECT 1 FROM common_task_detail ctd WHERE ctd.task_id = ct.id AND ctd.owner_user in
#{item}
) )
ORDER BY wishFinishTime asc, createTime desc
